package info.deltaindices.volumecamera;
import android.*;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings.Secure;import android.view.*;import android.widget.*;import androidx.activity.result.ActivityResultLauncher;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import java.util.*;
public final class MainActivity extends AppCompatActivity {
 private Switch armed;private EditText interval;private Spinner presses;private TextView state,driveState;
 private final ActivityResultLauncher<String[]> permissions=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->refresh());
 private final ActivityResultLauncher<Uri> folder=registerForActivityResult(new ActivityResultContracts.OpenDocumentTree(),uri->{if(uri!=null){getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);Settings.prefs(this).edit().putString(Settings.DRIVE,uri.toString()).apply();}refresh();});
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(build());requestNeeded();refresh();}
 private View build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(40,50,40,40);root.setBackgroundColor(Color.rgb(8,17,14));
  TextView title=text("VOLUME CAMERA",26);root.addView(title);root.addView(text("A persistent notification is shown while armed. Triggering opens a visible capture screen; Android shows its camera privacy indicator.",15));
  armed=new Switch(this);armed.setText("Arm background volume trigger");armed.setTextColor(Color.WHITE);root.addView(armed);state=text("",14);root.addView(state);
  root.addView(text("Capture interval (seconds, 2–3600)",14));interval=new EditText(this);interval.setInputType(2);interval.setTextColor(Color.WHITE);root.addView(interval);
  root.addView(text("Volume Up presses within 5 seconds",14));presses=new Spinner(this);presses.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"3","5"}));root.addView(presses);
  Button save=button("Save and apply");save.setOnClickListener(v->save());root.addView(save);Button access=button("Open Accessibility settings");access.setOnClickListener(v->startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS)));root.addView(access);
  Button drive=button("Choose Google Drive / cloud folder");drive.setOnClickListener(v->folder.launch(Settings.drive(this)));root.addView(drive);driveState=text("",13);root.addView(driveState);
  Button test=button("Start / stop capture now");test.setOnClickListener(v->startActivity(new Intent(this,CaptureActivity.class).setAction(CaptureActivity.ACTION_TOGGLE)));root.addView(test);return new ScrollView(this){{addView(root);}};}
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.WHITE);v.setPadding(0,12,0,12);return v;}private Button button(String s){Button b=new Button(this);b.setText(s);return b;}
 private void save(){int seconds;try{seconds=Integer.parseInt(interval.getText().toString());}catch(Exception e){seconds=5;}seconds=Math.max(2,Math.min(3600,seconds));Settings.prefs(this).edit().putBoolean(Settings.ARMED,armed.isChecked()).putInt(Settings.INTERVAL,seconds).putInt(Settings.PRESSES,presses.getSelectedItemPosition()==1?5:3).apply();ArmedService.sync(this);refresh();}
 private void requestNeeded(){ArrayList<String> p=new ArrayList<>();if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.CAMERA);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.POST_NOTIFICATIONS);if(Build.VERSION.SDK_INT<=28&&checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.WRITE_EXTERNAL_STORAGE);if(!p.isEmpty())permissions.launch(p.toArray(new String[0]));}
 private void refresh(){armed.setChecked(Settings.armed(this));interval.setText(String.valueOf(Settings.interval(this)));presses.setSelection(Settings.presses(this)==5?1:0);boolean enabled=Secure.getString(getContentResolver(),Secure.ENABLED_ACCESSIBILITY_SERVICES)!=null&&Secure.getString(getContentResolver(),Secure.ENABLED_ACCESSIBILITY_SERVICES).contains(getPackageName());state.setText(enabled?"Accessibility trigger enabled":"Enable this app in Accessibility settings before using the hardware trigger");driveState.setText(Settings.drive(this)==null?"Cloud mirroring off":"Cloud folder configured: "+Settings.drive(this));}
}
